// design/tokens.json (the Beavo design system tokens, merged with the app-only
// session/symptom colours) → tailwind.preset.js AND lib/tokens.ts.
// design/tokens.json is the single source of truth: edit it, then run
//   node scripts/build-tokens.mjs
// Never hand-edit the two generated files. `npm test` fails if they are stale.
import { readFileSync, writeFileSync } from 'node:fs';

const t = JSON.parse(readFileSync(new URL('../design/tokens.json', import.meta.url), 'utf8'));

const family = (name) => t[name].tokens.map((x) => [x.name, x.value.light ?? x.value]);
const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const px = (v) => Number(String(v).replace('px', ''));
const strip = (pairs, prefix) => pairs.map(([k, v]) => [k.replace(prefix, ''), v]);

// ---- Fonts: static TTFs bundled in assets/fonts/ (Google Fonts download, static/, OFL),
// registered under these names in app/_layout.tsx. Same names as @expo-google-fonts.
export const FONTS = {
  display: 'Baloo2_700Bold',
  displayExtraBold: 'Baloo2_800ExtraBold',
  body: 'Nunito_400Regular',
  bodySemiBold: 'Nunito_600SemiBold',
  bodyBold: 'Nunito_700Bold',
};
const fontFor = (fam, weight) =>
  fam === 'display'
    ? weight >= 800 ? FONTS.displayExtraBold : FONTS.display
    : weight >= 700 ? FONTS.bodyBold : weight >= 600 ? FONTS.bodySemiBold : FONTS.body;

// Motion is not in tokens.json (kit lib/tokens.ts values).
const MOTION = { pressScale: 0.96, fast: 150, base: 250, slow: 400, logoScreenHold: 1000, logoScreenFade: 250 };

const colors = family('color');
const spacing = strip(family('spacing'), 'space-');
const radius = strip(family('radius'), 'radius-');
const shadows = strip(family('shadow'), 'shadow-');
const sizes = family('size');
const styles = t.type.groups.flatMap((g) => g.styles.map((s) => ({ ...s, family: s.family ?? g.family })));

// ---- tailwind.preset.js ----
const preset = {
  theme: {
    extend: {
      colors: Object.fromEntries(colors),
      spacing: Object.fromEntries(spacing.map(([k, v]) => [`s${k}`, v])),
      borderRadius: Object.fromEntries(radius),
      boxShadow: Object.fromEntries(shadows),
      minHeight: { target: '48px', 'target-primary': '56px', tooth: '44px' },
      minWidth: { target: '48px', 'target-primary': '56px', tooth: '44px' },
      fontFamily: {
        display: [FONTS.display],
        'display-xb': [FONTS.displayExtraBold],
        body: [FONTS.body],
        'body-semibold': [FONTS.bodySemiBold],
        'body-bold': [FONTS.bodyBold],
        // Earlier class names, kept so existing screens keep working.
        'display-semi': [FONTS.display],
        numeric: [FONTS.displayExtraBold],
        'body-semi': [FONTS.bodySemiBold],
      },
      fontSize: Object.fromEntries(styles.map((s) => [s.name, [s.fontSize, { lineHeight: s.lineHeight }]])),
    },
  },
};

// ---- lib/tokens.ts ----
const obj = (pairs) => `{\n${pairs.map(([k, v]) => `  ${JSON.stringify(k)}: ${typeof v === 'string' ? JSON.stringify(v) : v},`).join('\n')}\n}`;
const sizeKey = { 'target-min': 'targetMin', 'target-primary': 'targetPrimary', 'target-tooth': 'targetTooth' };
const pressShadowValue = shadows.find(([k]) => k === 'press')[1];
const ts = `// Beavo design tokens (Riacho, light). GENERATED by scripts/build-tokens.mjs from
// design/tokens.json; don't hand-edit. Usage notes for every value live in
// design/tokens.json and beavo-design/design/README.md. NativeWind classes carry
// the same values (tailwind.preset.js); use these where classes can't reach:
// SVG fills, shadows, inline styles.

export const colors = ${obj(colors.map(([k, v]) => [camel(k), v]))} as const;

export const space = ${obj(spacing.map(([k, v]) => [k, px(v)]))} as const;

export const radius = ${obj(radius.map(([k, v]) => [k, px(v)]))} as const;

export const size = ${obj(sizes.map(([k, v]) => [sizeKey[k] ?? camel(k), px(v)]))} as const;

/** CSS box shadows (React Native 0.76+, both platforms). */
export const shadow = {
${shadows.map(([k, v]) => `  ${k}: { boxShadow: ${JSON.stringify(v)} },`).join('\n')}
} as const;

/** Static font files bundled in assets/fonts/ and registered under these names in app/_layout.tsx. Pick the family, never fontWeight. */
export const fonts = ${obj(Object.entries(FONTS))} as const;

export const type = {
${styles.map((s) => `  ${camel(s.name)}: { fontFamily: ${JSON.stringify(fontFor(s.family, s.fontWeight))}, fontSize: ${px(s.fontSize)}, lineHeight: ${px(s.lineHeight)} },`).join('\n')}
} as const;

/** Calm motion, no flicker. Respect Reduce Motion (Reanimated useReducedMotion). Durations in ms. */
export const motion = ${obj(Object.entries(MOTION))} as const;

// ---- Composites ----

/** Hairline for white-on-white edges (inputs, unchecked boxes). Decorative. */
export const hairline = { borderWidth: 1, borderColor: colors.line } as const;

/** Edge of a control that must be seen (checkbox, input, empty dot): 3:1 on white and cream. */
export const controlBorder = { borderWidth: 2, borderColor: colors.zoneLine } as const;

/** Resting depth under a primary button; collapses on press. Keep the key, change the value (Fabric). */
export const pressShadow = (pressed: boolean) => ({ boxShadow: pressed ? ${JSON.stringify(pressShadowValue.replace(/^0 \d+px 0/, '0 0px 0'))} : shadow.press.boxShadow });

export type ColorToken = keyof typeof colors;
`;

const banner = `// Beavo NativeWind/Tailwind preset (Riacho). GENERATED by scripts/build-tokens.mjs from design/tokens.json; don't hand-edit.\n`;
export const outputs = {
  'tailwind.preset.js': `${banner}module.exports = ${JSON.stringify(preset, null, 2)};\n`,
  'lib/tokens.ts': ts,
};

// Writes unless imported with BUILD_TOKENS_CHECK=1 (the freshness test compares instead).
if (!process.env.BUILD_TOKENS_CHECK) {
  for (const [file, text] of Object.entries(outputs)) writeFileSync(new URL(`../${file}`, import.meta.url), text);
  console.log(`tokens: wrote ${Object.keys(outputs).join(' and ')} (${colors.length} colours)`);
}
